class Solution {
    bool isVowel(char c) {
        c = tolower(c);
        return c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u';
    }
public:
    string toGoatLatin(string sentence) {
        stringstream ss(sentence);
        string w, res = "";
        int idx = 1;
        while (ss >> w) {
            if (idx > 1) res += " ";
            if (isVowel(w[0])) {
                res += w + "ma";
            } else {
                res += w.substr(1) + w[0] + "ma";
            }
            res += string(idx, 'a');
            idx++;
        }
        return res;
    }
};

class Solution {
    public String toGoatLatin(String sentence) {
        Set<Character> vowels = new HashSet<>(Arrays.asList('a','e','i','o','u','A','E','I','O','U'));
        String[] words = sentence.split(" ");
        StringBuilder res = new StringBuilder();
        for (int i = 0; i < words.length; i++) {
            if (i > 0) res.append(" ");
            String w = words[i];
            if (vowels.contains(w.charAt(0))) {
                res.append(w).append("ma");
            } else {
                res.append(w.substring(1)).append(w.charAt(0)).append("ma");
            }
            for (int k = 0; k <= i; k++) res.append('a');
        }
        return res.toString();
    }
}

var toGoatLatin = function(sentence) {
    const vowels = new Set(['a','e','i','o','u','A','E','I','O','U']);
    const words = sentence.split(' ');
    const ans = [];
    for (let i = 0; i < words.length; i++) {
        const w = words[i];
        let transformed;
        if (vowels.has(w[0])) {
            transformed = w + 'ma';
        } else {
            transformed = w.slice(1) + w[0] + 'ma';
        }
        transformed += 'a'.repeat(i + 1);
        ans.push(transformed);
    }
    return ans.join(' ');
};
